INSERT INTO zen_scripts (id,title,category,version,description,requirements,installation,usage,changelog,published,file_name,file_size,sha256,file_data,access_tier,price_halalas)
VALUES ('ca64101c-4020-5830-abb6-863a0f99b2d6','Spartan 2.0','GPC','2.0','ملف GPC أرسله مشاري، متاح للتنزيل من القسم المجاني. النسخة الأصلية محفوظة دون تعديل. لم يُختبر على جهاز Zen. يذكر الملف أنه يحتاج إلى مشغّل Spartan وترخيص صالح منفصل؛ التنزيل لا يتضمن الترخيص.','جهاز متوافق وZen Studio. راجع تعليمات وشروط صاحب السكربت داخل الملف قبل الاستخدام. يتطلب مشغّل Spartan وترخيصه من صاحب المنتج.','نزّل الملف وافتحه في Zen Studio. اقرأ تعليماته، ثم افحصه بالمترجم قبل برمجته على الجهاز باستخدام الأدوات الرسمية.','تختلف الأزرار والإعدادات حسب السكربت؛ راجع التعليقات والقوائم داخل الملف. لا توجد ضمانات توافق قبل الاختبار.','إضافة الملف الأصلي كما رفعه المشرف.',true,'Spartan_2.0.gpc',214550,'9b6750688b2a9cc2a9bfb8d3f811c8bd666ac86f60753c5db0959c362c80c7d1',decode('', 'base64'),'free',0)
